import test from 'node:test';import assert from 'node:assert/strict';
import {lessons,topic} from '../dist/geography/content.js';
import {specimens,requirements,scene} from '../dist/geography/model.js';
import {restore,validPath,geoGates,KEY,choiceIndices,eligibleGeography} from '../dist/geography/studio.js';
import {STORAGE_KEY} from '../dist/progress.js';import {MATHS_KEY} from '../dist/maths/mastery.js';
test('Geography has one hundred and forty-five untiered lessons across ten built topics with unique original question and concept IDs',()=>{assert.equal(lessons.length,145);const ids=new Set();for(const l of lessons){assert.ok([topic.id,'geography.a.coasts','geography.a.rivers','geography.a.glaciers','geography.a.weather','geography.a.ecosystems','geography.a.cities','geography.a.development','geography.a.resources-core','geography.a.energy'].includes(l.topicId));assert.equal(l.cards.length,3);assert.equal(l.practice.length,3);assert.equal(l.check.length,4);for(const q of [...l.practice,...l.check]){assert.ok(!ids.has(q.id));ids.add(q.id);assert.ok(q.id.startsWith('geo.a.')&&q.concept.startsWith('geo.a.'));assert.ok(q.options[q.answer]&&q.why);}}assert.equal(ids.size,1015);assert.notEqual(KEY,STORAGE_KEY);assert.notEqual(KEY,MATHS_KEY);});
test('all24 official option combinations are accepted while over-selection duplicate and missing choices reject',()=>{let n=0;for(const landscapes of [['coasts','rivers'],['coasts','glaciers'],['rivers','glaciers']])for(const resource of ['energy','water'])for(const physical of ['coasts','rivers'])for(const human of ['urban','rural']){assert.ok(validPath({landscapes,resource,physical,human}));n++;}assert.equal(n,24);const p={landscapes:['coasts','rivers'],resource:'water',physical:'coasts',human:'rural'};for(const bad of [null,{}, {...p,landscapes:['coasts','coasts']},{...p,landscapes:['coasts','rivers','glaciers']},{...p,human:'mountains'},{...p,resource:undefined}])assert.equal(validPath(bad),false);});
test('completion requires every learning card challenge and compared model view plus independent success',()=>{for(const l of lessons){const p={seen:[0,1,2],observed:[...requirements[l.model]],passed:l.tasks.map((_,i)=>i),practice:Object.fromEntries(l.practice.map(q=>[q.id,{correct:true}])),checks:Object.fromEntries(l.check.map(q=>[q.id,q.answer]))};assert.ok(geoGates(l,p).every(Boolean));let x=structuredClone(p);x.observed.pop();assert.equal(geoGates(l,x)[1],false);x=structuredClone(p);x.passed.pop();assert.equal(geoGates(l,x)[1],false);x=structuredClone(p);x.seen.pop();assert.equal(geoGates(l,x)[0],false);x=structuredClone(p);delete x.practice[l.practice[0].id];assert.equal(geoGates(l,x)[2],false);x=structuredClone(p);x.checks[l.check[0].id]=(l.check[0].answer+1)%3;assert.equal(geoGates(l,x)[3],false);}});
test('pathway model drafts answers and unfinished recall survive restore without mixing subject storage',()=>{const p={landscapes:['coasts','glaciers'],resource:'water',physical:'coasts',human:'rural'},id=lessons[0].id,q=lessons[0].check[0];const s={version:1,lessonId:id,pathway:p,lessons:{[id]:{selection:'schist',observed:['granite'],passed:[0],checks:{[q.id]:q.answer}}},concepts:{[q.concept]:{needsReview:true}},review:{ids:[q.id],answers:{[q.id]:q.answer},index:0}};const r=restore(JSON.stringify(s));assert.deepEqual(r,s);assert.equal(restore('{').lessonId,id);assert.equal(restore(JSON.stringify({...s,version:99})).pathway,null);assert.equal(restore(JSON.stringify({...s,review:{ids:['invented']}})).review,null);});
test('each model selection renders finite labelled evidence and relative resistance can be reversed',()=>{for(const l of lessons)for(const selected of requirements[l.model]){const svg=scene(l.model,selected,Number(selected)||0);assert.ok(svg.includes('role="img"')||svg.includes('<table')||svg.includes('<img')&&svg.includes('alt='));assert.ok(!/NaN|undefined|Infinity/.test(svg));}assert.ok(scene('profile','left').includes('Left: 90'));assert.ok(scene('profile','right').includes('Right: 90'));for(const k of ['granite','basalt'])assert.match(specimens[k][1],/Igneous/);for(const k of ['chalk','sandstone'])assert.match(specimens[k][1],/Sedimentary/);for(const k of ['slate','schist'])assert.match(specimens[k][1],/Metamorphic/);});

test('answer order is reproducible without making the first button a reliable answer cue',()=>{let first=0;for(const l of lessons)for(const q of [...l.practice,...l.check]){const a=choiceIndices(q.id,q.options.length);assert.deepEqual(a,choiceIndices(q.id,q.options.length));assert.equal(new Set(a).size,q.options.length);if(a[0]===q.answer)first++;}assert.ok(first<lessons.length*7*.6);});

test('coastal pathway excludes optional lessons but preserves their existing saved progress',()=>{const coast=lessons.find(l=>l.option==='coasts'),p={landscapes:['rivers','glaciers'],resource:'water',physical:'rivers',human:'rural'};assert.equal(lessons.filter(l=>eligibleGeography(l,p )).length,121);assert.equal(lessons.filter(l=>eligibleGeography(l,{...p,landscapes:['rivers','coasts']} )).length,117);assert.equal(lessons.filter(l=>eligibleGeography(l,null )).length,145);const saved=restore(JSON.stringify({version:1,pathway:p,lessonId:coast.id,lessons:{[coast.id]:{observed:['slump'],seen:[0]}}}));assert.deepEqual(saved.lessons[coast.id].observed,['slump']);assert.equal(eligibleGeography(coast,saved.pathway),false);});
test('coastal model beginnings, middles and ends remain valid with meaningful movement and non-colour descriptions',()=>{for(const l of lessons.filter(l=>l.model.startsWith('coast-'))){for(const v of requirements[l.model]){const frames=[0,.5,1].map(t=>scene(l.model,v,t));for(const f of frames){assert.ok(!/NaN|undefined|Infinity/.test(f));assert.match(f,/aria-label=/);assert.match(f,/geo-caption/);}assert.notEqual(frames[0],frames[1]);}}});

test('Swanage uses a credited dated authentic photograph and static evidence rather than a fabricated time series',()=>{const l=lessons.find(l=>l.model==='swanage');assert.ok(l);const a=scene('swanage','photo',0);assert.match(a,/old-harry-nilfanion.jpg/);assert.match(a,/17 October 2013/);assert.match(a,/Nilfanion/);assert.match(a,/creativecommons.org/);assert.match(a,/alt=/);assert.equal(a,scene('swanage','photo',1));assert.notEqual(a,scene('swanage','geology',0));});

import {riverCases,discharge,gauge} from '../dist/geography/river-data.js';
import {isProcessView} from '../dist/geography/model.js';
test('river volume comparisons isolate area and speed and retain discharge units',()=>{const a=riverCases.base;assert.equal(discharge(a.area,a.speed),4);assert.equal(discharge(riverCases.area.area,riverCases.area.speed),8);assert.equal(discharge(riverCases.speed.area,riverCases.speed.speed),8);assert.equal(discharge(riverCases.both.area,riverCases.both.speed),16);assert.equal(discharge(6,.5),3);const l=lessons.find(l=>l.id.endsWith('tees-flow'));assert.match(l.check[0].options[l.check[0].answer],/^3m³\/s$/);assert.match(scene(l.model,'both',.5),/16m³\/s/);});
test('genuine EA stage evidence is dated and static; river comparisons do not animate fake measurement histories',()=>{assert.equal(gauge.id,'F3504');assert.equal(gauge.unit,'m');assert.deepEqual(gauge.observations.map(x=>x.value),[3.092,.297]);assert.equal(isProcessView('river-weather','record'),false);assert.equal(isProcessView('river-courses','upper'),false);assert.equal(isProcessView('river-flow','base'),true);assert.equal(isProcessView('river-flow','route'),false);const table=scene('river-weather','record',0);assert.equal(table,scene('river-weather','record',1));assert.match(table,/2013/);assert.match(table,/2017/);assert.match(table,/not a live reading/i);assert.match(table,/gauge datum/i);for(const l of lessons.filter(l=>l.option==='rivers'))for(const v of requirements[l.model]){const a=scene(l.model,v,0),b=scene(l.model,v,.5);assert.ok(!/NaN|undefined|Infinity/.test(a+b));if(isProcessView(l.model,v))assert.notEqual(a,b);else assert.equal(a,b);}const nonriver={landscapes:['coasts','glaciers'],resource:'water',physical:'coasts',human:'rural'};assert.equal(lessons.filter(l=>eligibleGeography(l,nonriver )).length,120);});

import {storm,highForcePhoto} from '../dist/geography/model-rivers2.js';
test('same-storm hydrographs have independent peak times and retain an honest evidence type',()=>{const peak=a=>storm.hours[a.indexOf(Math.max(...a))];assert.equal(peak(storm.rain),1);assert.equal(peak(storm.rural)-peak(storm.rain),3);assert.equal(peak(storm.urban)-peak(storm.rain),1);assert.equal(Math.max(...storm.urban),36);const graph=scene('river-floods','graph',0);assert.equal(graph,scene('river-floods','graph',1));assert.match(graph,/INVENTED/);assert.match(graph,/mm\/hour/);assert.match(graph,/m³\/s/);const item=lessons.find(l=>l.model==='river-floods').check[1];assert.equal(item.hydrograph,true);assert.equal(item.options[item.answer],'3hours');});
test('High Force independent stimulus is dated attributed and contains no teaching explanation',()=>{assert.match(highForcePhoto(false),/Sandy Gerrard/);assert.match(highForcePhoto(false),/29 September 2021/);assert.match(highForcePhoto(false),/by-sa\/2.0/);assert.doesNotMatch(highForcePhoto(false),/Look for/);assert.match(highForcePhoto(true),/cannot establish an erosion rate/);assert.equal(isProcessView('river-falls','photo'),false);assert.equal(isProcessView('river-falls','waterfall'),true);assert.equal(isProcessView('river-management','zoning'),false);});
test('new Discover evidence follows the explanation and all mapped views belong to that model',()=>{for(const l of lessons.filter(l=>l.cardViews)){assert.equal(l.cardViews.length,l.cards.length);for(const v of l.cardViews)assert.ok(requirements[l.model].includes(v));}const falls=lessons.find(l=>l.model==='river-falls');assert.deepEqual(falls.cardViews,['spurs','waterfall','photo']);assert.equal(isProcessView(falls.model,falls.cardViews[0]),false);assert.equal(isProcessView(falls.model,falls.cardViews[1]),true);assert.equal(isProcessView(falls.model,falls.cardViews[2]),false);});

import {uplandViews,uplandAnimated} from '../dist/geography/model-glaciers.js';
test('upland process frames remain labelled while genuine evidence and comparisons stay static',()=>{for(const [k,views] of Object.entries(uplandViews))for(const [v] of views){const f=[0,.5,1].map(t=>scene(k,v,t));for(const a of f){assert.doesNotMatch(a,/NaN|undefined|Infinity/);assert.ok(a.includes('aria-label=')||a.includes('alt='));}assert.equal(isProcessView(k,v),uplandAnimated(k,v));if(uplandAnimated(k,v))assert.notEqual(f[0],f[1]);else assert.equal(f[0],f[1]);}assert.match(scene('glacier-ice','flow',.5),/ice particles still move downslope/i);assert.match(scene('glacier-corrie','arete',.5),/not a heap deposited/i);assert.match(scene('river-tees-study','storage',.5),/2022/);});

import {glacierViews2,glacierAnimated2} from '../dist/geography/model-glaciers2.js';
test('remaining glacial landform views keep process/evidence decisions and qualify variable formation',()=>{for(const [k,views] of Object.entries(glacierViews2))for(const [v] of views){const f=[0,.5,1].map(t=>scene(k,v,t));for(const a of f){assert.doesNotMatch(a,/NaN|undefined|Infinity/);assert.match(a,/aria-label=/);}assert.equal(isProcessView(k,v),glacierAnimated2(k,v));if(glacierAnimated2(k,v))assert.notEqual(f[0],f[1]);else assert.equal(f[0],f[1]);}assert.match(scene('glacier-roche','reverse',.5),/stoss side is now on the right/);assert.match(scene('glacier-streamlined','drumlin',.5),/no single universal/);assert.match(scene('glacier-moraine','retreat',.5),/Ice still flows downslope/);});

import {developmentViews,developmentAnimated,waterCases,waterBudget,thirlmerePhoto} from '../dist/geography/model-glaciers3.js';
test('upland development water budgets balance independently and named photo is genuine static neutral evidence',()=>{assert.equal(waterBudget(waterCases.store),1050);assert.equal(waterBudget(waterCases.dry),800);assert.equal(waterBudget({start:700,inflow:100,supply:80,loss:20}),700);assert.match(thirlmerePhoto(false),/Jorge Franganillo/);assert.match(thirlmerePhoto(false),/10 August 2012/);assert.match(thirlmerePhoto(false),/by\/2.0/);assert.doesNotMatch(thirlmerePhoto(false),/does not establish/);for(const [k,vs] of Object.entries(developmentViews))for(const [v] of vs){const a=scene(k,v,0),b=scene(k,v,.5);assert.doesNotMatch(a+b,/NaN|undefined|Infinity/);assert.equal(isProcessView(k,v),developmentAnimated(k,v));if(developmentAnimated(k,v))assert.notEqual(a,b);else assert.equal(a,b);}assert.equal(lessons.find(l=>l.model==='glacier-thirlmere').check[2].thirlmere,true);});

import {weatherViews,weatherAnimated,cellBands,pressureBands} from '../dist/geography/model-weather.js';
test('shared weather cell directions and evidence decisions preserve physical meaning and option independence',()=>{assert.deepEqual(cellBands.map(c=>[c.from,c.to]),[[0,30],[30,60],[60,90]]);assert.deepEqual(cellBands.map(c=>c.surface),['equatorward','poleward','equatorward']);assert.deepEqual(pressureBands.map(p=>p.motion),['rising','sinking','rising','sinking']);for(const [k,views] of Object.entries(weatherViews))for(const [v] of views){const a=scene(k,v,0),b=scene(k,v,.5);assert.doesNotMatch(a+b,/NaN|undefined|Infinity/);assert.match(a,/aria-label=/);assert.equal(isProcessView(k,v),weatherAnimated(k,v));if(weatherAnimated(k,v))assert.notEqual(a,b);else assert.equal(a,b);}for(const l of lessons.filter(l=>l.topicId==='geography.a.weather'))for(const landscapes of [['coasts','rivers'],['coasts','glaciers'],['rivers','glaciers']])assert.equal(eligibleGeography(l,{landscapes}),true);assert.match(scene('weather-evidence','rings'),/not a measured chronology/);assert.match(scene('weather-causes','compare'),/does not by itself explain rapid recent warming/);});

import {cet} from '../dist/geography/climate-data.js';
import {weatherViews2,weatherAnimated2,climateGraph} from '../dist/geography/model-weather2.js';
import {readFileSync} from 'node:fs';
test('HadCET charts reproduce published complete annual values and equal-length averages with neutral independent stimuli',()=>{const raw=readFileSync(new URL('../dist/geography/data/hadcet-seasonal-2026-10-23.txt',import.meta.url),'utf8');const annual=raw.split(/\r?\n/).map(s=>s.trim().split(/\s+/)).filter(p=>p.length===6&&/^\d{4}$/.test(p[0])&&+p[0]<=2025).map(p=>[+p[0],+p[5]]);assert.deepEqual(cet.annual,annual);assert.equal(annual.length,367);assert.equal(annual.at(-1)[0],2025);for(const p of cet.periods){const values=annual.filter(([y])=>y>=p.from&&y<=p.to).map(x=>x[1]);assert.equal(values.length,30);assert.equal(p.mean,Math.round(values.reduce((a,b)=>a+b)/30*100)/100);}assert.deepEqual(cet.periods.map(p=>p.mean),[8.84,9.46,10.27]);const l=lessons.find(l=>l.id.endsWith('uk-climate-history'));assert.equal(l.check[0].options[l.check[0].answer],'0.81°C');assert.ok(annual.find(x=>x[0]===2022)[1]>annual.find(x=>x[0]===2021)[1]);for(const v of ['line','bars','recent','table']){const chart=climateGraph(v);assert.match(chart,/Central England/);assert.match(chart,/OGL3.0/);assert.doesNotMatch(chart,/correct answer|highest mean|0.81°C/i);assert.doesNotMatch(chart,/NaN|undefined|Infinity/);}assert.match(climateGraph('table'),/<caption>/);});
test('new climate process views move while measured charts and comparison evidence stay static across all phases',()=>{for(const[k,views]of Object.entries(weatherViews2))for(const[v]of views){const frames=[0,.5,1].map(t=>scene(k,v,t));assert.ok(frames.every(f=>!(/NaN|undefined|Infinity/).test(f)));assert.equal(isProcessView(k,v),weatherAnimated2(k,v));if(weatherAnimated2(k,v))assert.notEqual(frames[0],frames[1]);else assert.equal(frames[0],frames[1]);}assert.match(scene('weather-impacts','glacier',.5),/continue moving downslope/);assert.match(scene('weather-greenhouse','enhanced',.5),/Some energy escapes/);assert.match(scene('weather-uk-history','millennium'),/cannot measure the earlier centuries/);});

import {katrinaTrack,atlanticSeasons,windCategory} from '../dist/geography/cyclone-data.js';
import {weatherViews3,weatherAnimated3,cycloneEvidence,haiyanSatellite} from '../dist/geography/model-weather3.js';
test('cyclone wind classifications respect NHC knot boundaries and keep storm surge outside the scale',()=>{for(const[v,c]of[[63,null],[64,1],[82,1],[83,2],[95,2],[96,3],[110,3],[112,3],[113,4],[136,4],[137,5],[150,5],[NaN,null],[Infinity,null]])assert.equal(windCategory(v),c);const l=lessons.find(l=>l.id.endsWith('.katrina'));assert.equal(l.practice[1].options[l.practice[1].answer],'Category3');assert.match(l.cards[0][1],/110kt/);assert.match(l.cards[0][1],/1110UTC/);assert.deepEqual(atlanticSeasons.map(s=>s.named),[30,14]);for(const s of atlanticSeasons)assert.ok(s.named>=s.hurricanes&&s.hurricanes>=s.major);assert.doesNotMatch(cycloneEvidence('scale'),/110kt lies|correct answer|Category3 is/i);});
test('dated Katrina coordinates use north and west correctly and source statistics retain definitions',()=>{const source=JSON.parse(readFileSync(new URL('../dist/geography/data/katrina-best-track-subset.json',import.meta.url),'utf8'));assert.deepEqual(katrinaTrack,source.observations);assert.equal(katrinaTrack.length,29);assert.equal(new Set(katrinaTrack.map(p=>p.day+':'+p.time)).size,29);for(let i=1;i<katrinaTrack.length;i++){const hours=p=>p.day*24+Number(p.time.slice(0,2));assert.equal(hours(katrinaTrack[i])-hours(katrinaTrack[i-1]),6);}const a=katrinaTrack.find(p=>p.day===28&&p.time==='1800'),b=katrinaTrack.find(p=>p.day===29&&p.time==='1200');assert.deepEqual([a.lat,a.lon,a.wind],[26.3,-88.6,150]);assert.deepEqual([b.lat,b.lon,b.wind],[29.5,-89.6,110]);assert.ok(b.lat>a.lat);assert.equal(520+565+307,1392);assert.match(cycloneEvidence('katrina'),/Indeterminate cause/);assert.match(cycloneEvidence('haiyan'),/Of affected boats/);assert.match(haiyanSatellite(false),/7November2013/);assert.match(haiyanSatellite(false),/NASA LANCE\/EOSDIS/);assert.doesNotMatch(haiyanSatellite(false),/does not measure casualties/);assert.match(scene('weather-cyclone-patterns','track28'),/26.3°N/);assert.match(scene('weather-cyclone-patterns','track28'),/88.6°W/);assert.doesNotMatch(scene('weather-haiyan','surge',.5),/M245 285V220/);});
test('cyclone process sequences move but actual satellite tracks and evidence remain fixed',()=>{for(const[k,vs]of Object.entries(weatherViews3))for(const[v]of vs){const f=[0,.5,1].map(t=>scene(k,v,t));assert.ok(f.every(s=>!/NaN|undefined|Infinity/.test(s)));assert.ok(f[0].includes('role="img"')||f[0].includes('<table')||f[0].includes('alt='));assert.equal(isProcessView(k,v),weatherAnimated3(k,v));if(weatherAnimated3(k,v))assert.notEqual(f[0],f[1]);else assert.equal(f[0],f[1]);}assert.match(scene('weather-cyclone-form','cycle'),/Southern Hemisphere surface rotation is clockwise/);assert.match(scene('weather-cyclone-patterns','change'),/Two Atlantic seasons cannot establish a long-term trend/);});

import {rainfall,waterCases as droughtWaterCases,endStorage} from '../dist/geography/drought-data.js';
import {weatherViews4,weatherAnimated4,droughtEvidence,droughtRain} from '../dist/geography/model-weather4.js';
test('NASA monthly rates become annual totals with real month lengths and no annual13 double count',()=>{const raw=JSON.parse(readFileSync(new URL('../dist/geography/data/power-melbourne-1990-2015.json',import.meta.url),'utf8'));assert.equal(raw.parameters.PRECTOTCORR.units,'mm/day');assert.equal(raw.header.sources[0],'MERRA2');assert.deepEqual(raw.geometry.coordinates.slice(0,2),[144.96,-37.81]);assert.equal(rainfall.annual.length,26);const v=raw.properties.parameter.PRECTOTCORR;for(const[y,total]of rainfall.annual){let sum=0;for(let m=1;m<=12;m++){const days=new Date(Date.UTC(y,m,0)).getUTCDate(),x=v[`${y}${String(m).padStart(2,'0')}`];assert.ok(Number.isFinite(x)&&x>=0);sum+=x*days;}assert.equal(total,Math.round(sum));}const by=Object.fromEntries(rainfall.annual);assert.equal(by[2006],487);assert.equal(by[2010],935);assert.equal(by[2010]-by[2006],448);const l=lessons.find(l=>l.id.endsWith('drought-patterns'));assert.equal(l.check[1].options[l.check[1].answer],'448mm');assert.match(droughtRain(),/gridded precipitation estimates/);assert.match(droughtRain(),/Not a rain-gauge record/);assert.match(droughtRain(),/Read chart values/);});
test('drought teaching water budgets conserve storage and source calculations preserve denominators',()=>{assert.equal(endStorage(droughtWaterCases.balanced),100);assert.equal(endStorage(droughtWaterCases.dry),70);assert.equal(endStorage(droughtWaterCases.saving),85);assert.equal(endStorage({start:50,inflow:12,use:8,loss:4}),50);assert.equal(endStorage(droughtWaterCases.saving)-endStorage(droughtWaterCases.dry),15);assert.equal(97.5-33,64.5);assert.equal(258000-133000,125000);assert.equal(2800000*.8,2240000);for(const[k,word]of[['storage','different'],['mortality','Modelled'],['coverage','4August2011']])assert.ok(droughtEvidence(k).toLowerCase().includes(word.toLowerCase()));const som=lessons.find(l=>l.id.endsWith('somalia-drought'));assert.equal(som.check[1].options[som.check[1].answer],'125,000');assert.match(scene('weather-australia-drought','saving',.5),/not Murray or Melbourne observations/);});
test('drought process frames move while dated rainfall storage and mortality evidence stay still',()=>{for(const[k,vs]of Object.entries(weatherViews4))for(const[v]of vs){const f=[0,.5,1].map(t=>scene(k,v,t));assert.ok(f.every(s=>!/NaN|undefined|Infinity/.test(s)));assert.ok(f[0].includes('role="img"')||f[0].includes('<table'));assert.equal(isProcessView(k,v),weatherAnimated4(k,v));if(weatherAnimated4(k,v))assert.notEqual(f[0],f[1]);else assert.equal(f[0],f[1]);}assert.match(scene('weather-drought-causes','forest'),/need not always reduce river flow/);assert.match(scene('weather-somalia-drought','cascade'),/not.*all droughts produce famine/);});

import {ecoViews,ecoAnimated,climateExamples,climateRange,ecoEvidence} from '../dist/geography/model-ecosystems.js';
test('ecosystem climate summaries keep source monthly values and signed ranges on matching axes',()=>{assert.deepEqual(climateExamples.map(climateRange),[1,41]);assert.deepEqual(climateExamples.map(x=>x.rain.reduce((a,b)=>a+b)),[2323,266]);for(const x of climateExamples){assert.equal(x.rain.length,12);assert.equal(x.temp.length,12);assert.ok(x.rain.every(v=>v>=0));}const l=lessons.find(l=>l.model==='eco-controls');assert.equal(l.check[0].options[l.check[0].answer],'41°C');assert.match(ecoEvidence(),/Read chart values/);assert.match(ecoEvidence(),/1970–2000/);assert.match(ecoEvidence(),/scope="row"/);assert.doesNotMatch(ecoEvidence(),/41°C|correct answer|larger range/);});
test('ecosystem causal pathways move while biome locators and real climate evidence remain static',()=>{for(const[k,vs]of Object.entries(ecoViews))for(const[v]of vs){const f=[0,.5,1].map(t=>scene(k,v,t));assert.ok(f.every(s=>!/NaN|undefined|Infinity/.test(s)));assert.match(f[0],/role="img"/);assert.equal(isProcessView(k,v),ecoAnimated(k,v));if(ecoAnimated(k,v))assert.notEqual(f[0],f[1]);else assert.equal(f[0],f[1]);}assert.equal(ecoViews['eco-biomes'].length,7);assert.match(scene('eco-resources','mine',.5),/geological origins/);assert.match(scene('eco-uk-land','wetland'),/not.*GIS analysis/);assert.match(scene('eco-uk-marine','protect',.5),/does not establish/);});

