test('sanitation target reach and policy categories distinguish historical estimates from delivered benefits',()=>{assert.equal(sanitationData.estimatedReach/sanitationData.target*100,40);assert.equal(sanitationData.target-sanitationData.estimatedReach,600000);assert.equal(budgetGap(100,70),30);assert.equal(budgetGap(60,80),0);assert.match(policyEvidence('reach'),/1996–2005/);assert.match(policyEvidence('reach'),/not all Mumbai residents/);assert.doesNotMatch(policyEvidence('reach'),/600,000|40%|disease.*fell/);assert.match(policyEvidence('entitlement'),/350 sq ft/);assert.match(policyEvidence('entitlement'),/within MMR/);assert.match(policyEvidence('entitlement'),/not proof of homes delivered/);});
test('GHSL source windows have identical real cell alignment units and exact source samples',()=>{const raw=JSON.parse(readFileSync(new URL('../dist/geography/data/mumbai-ghsl-window.json',import.meta.url),'utf8'));assert.deepEqual(spatialData,raw);assert.equal(raw.crs,'ESRI:54009');assert.equal(raw.cellMetres,1000);assert.equal(raw.licence,'CC BY 4.0');assert.deepEqual(raw.rows.map(r=>r.epoch),[1975,2020]);assert.deepEqual(raw.rows[0].bounds,raw.rows[1].bounds);for(const e of raw.rows){assert.equal(e.values.length,60);assert.ok(e.values.every(r=>r.length===60&&r.every(v=>Number.isInteger(v)&&v>=0&&v<=1000000)));assert.match(e.source,/R7_C26.zip$/);assert.match(e.sourceZipSHA256,/^[a-f0-9]{64}$/);}assert.deepEqual(spatialSamples.map(p=>p.values),[[187430,242604],[3959,38409]]);assert.equal(242604-187430,55174);assert.equal(38409-3959,34450);assert.match(policyEvidence('compare'),/one-kilometre cells/);assert.match(policyEvidence('late'),/not photographs/);assert.doesNotMatch(policyEvidence('sample'),/55,174|34,450|larger increase/);assert.equal(mumbaiManagementLessons[4].check[0].policyEvidence,'sample');});
test('twenty Mumbai management views separate nine processes from eleven still comparisons',()=>{let n=0,m=0;for(const[k,vs]of Object.entries(policyViews))for(const[v]of vs){n++;const f=[0,.5,1].map(t=>scene(k,v,t));assert.ok(f.every(s=>s.includes('role="img"')&&!/NaN|undefined|Infinity/.test(s)));assert.equal(isProcessView(k,v),policyAnimated(k,v));if(policyAnimated(k,v)){m++;assert.notEqual(f[0],f[1]);}else assert.ok(f.every(s=>s===f[0]));}assert.equal(n,20);assert.equal(m,9);assert.match(scene('city-mumbai-services','demand',1),/Illustrative gap: 30 homes/);});

import {globalDevelopmentLessons,globalDevelopmentTopic} from '../dist/geography/content-development.js';
import {globalDevelopmentViews,globalDevelopmentAnimated,developmentData,developmentPaths,developmentEvidence,hdiCategory,incomeDistribution,gini,outputPerPerson} from '../dist/geography/model-development.js';
test('first development batch maps five precise statements with shared eligibility and new stable identities',()=>{assert.equal(globalDevelopmentTopic.id,'geography.a.development');assert.deepEqual(globalDevelopmentLessons.map(l=>l.refs[0]),['5.1a','5.1b','5.1c','5.2a','5.2b']);for(const l of globalDevelopmentLessons){assert.equal(l.option,undefined);assert.equal(l.topicId,globalDevelopmentTopic.id);for(const v of l.cardViews)assert.ok(requirements[l.model].includes(v));for(const q of [...l.practice,...l.check])assert.ok(q.id.startsWith('geo.a.d1.')&&q.concept.startsWith('geo.a.development.'));}const s=JSON.stringify(globalDevelopmentLessons).toLowerCase();for(const w of ['economic','social','political','cultural','technolog','food','water','gini','corruption','historic','physical'])assert.ok(s.includes(w),w);});
test('development source series retain HDI reference year PPP GDP units and true country geometry joins',()=>{const raw=JSON.parse(readFileSync(new URL('../dist/geography/data/development-selected.json',import.meta.url),'utf8')),geo=JSON.parse(readFileSync(new URL('../dist/geography/data/world-natural-earth.geojson',import.meta.url),'utf8'));assert.deepEqual(developmentData,raw);assert.equal(raw.hdi.year,2023);assert.equal(raw.hdi.countries.length,193);assert.equal(new Set(raw.hdi.countries.map(c=>c.code)).size,193);assert.equal(raw.gdp.year,2023);assert.equal(raw.gdp.indicator,'NY.GDP.PCAP.PP.CD');for(const c of raw.gdp.selected){const r=raw.gdp.response[1].find(r=>r.countryiso3code===c.code);assert.equal(c.gdp,r.value);assert.equal(c.hdi,raw.hdi.countries.find(r=>r.code===c.code).hdi);}const q=raw.gdp.selected.find(c=>c.code==='QAT'),n=raw.gdp.selected.find(c=>c.code==='NOR');assert.ok(q.gdp>n.gdp&&q.hdi<n.hdi);assert.equal(q.hdi,.886);assert.equal(n.hdi,.970);assert.equal(developmentPaths.length,geo.features.length);assert.equal(geo.features.length,176);for(const c of ['BRA','NOR','GBR','IND','NER'])assert.ok(geo.features.some(f=>f.properties.ADM0_A3===c)&&developmentPaths.some(p=>p.code===c));assert.equal(hdiCategory(.549),'Low');assert.equal(hdiCategory(.55),'Medium');assert.equal(hdiCategory(.7),'High');assert.equal(hdiCategory(.8),'Very High');assert.equal(hdiCategory(undefined),'missing');assert.match(developmentEvidence('world'),/Grey: missing/);assert.doesNotMatch(developmentEvidence('pair'),/Qatar.*ranks first|correct answer|Norway.*highest/);});
test('development distributions conserve fixed total and mean while inequality changes and date-specific evidence stays neutral',()=>{for(let i=0;i<=100;i++){const a=incomeDistribution(i/100);assert.ok(Math.abs(a.reduce((x,y)=>x+y,0)-100)<1e-9);assert.ok(a.every(x=>x>=0));assert.ok(gini(a)>=-1e-10&&gini(a)<=60+1e-10);}assert.equal(gini([20,20,20,20,20]),0);assert.ok(Math.abs(gini([5,5,5,5,80])-60)<1e-10);assert.equal(outputPerPerson(300000000,15000),20000);assert.equal(outputPerPerson(200000000,10000),20000);assert.equal(developmentData.uk.year,2024);assert.equal(developmentData.uk.provisional,true);assert.equal(developmentData.uk.regions.length,13);assert.equal(36487-20562,15925);assert.match(developmentEvidence('uk'),/2024 provisional/);assert.match(developmentEvidence('uk'),/not wages or money left after rent/);assert.doesNotMatch(developmentEvidence('uk'),/15,925|London.*highest/);assert.equal(81-39,42);assert.equal(developmentData.cpi.year,2025);assert.equal(developmentData.cpi.countries.find(c=>c.code==='NOR').score,81);assert.equal(developmentData.cpi.countries.find(c=>c.code==='IND').score,39);assert.match(developmentEvidence('cpi'),/not a percentage of corrupt people/);assert.equal(globalDevelopmentLessons[2].check[0].developmentEvidence,'pair');});
test('twenty global development views distinguish ten causal or conserved-example loops from ten still evidence views',()=>{let n=0,m=0;for(const[k,vs]of Object.entries(globalDevelopmentViews))for(const[v]of vs){n++;const f=[0,.5,1].map(t=>scene(k,v,t));assert.ok(f.every(s=>(s.includes('role="img"')||s.includes('<table'))&&!/NaN|undefined|Infinity/.test(s)));assert.equal(isProcessView(k,v),globalDevelopmentAnimated(k,v));if(globalDevelopmentAnimated(k,v)){m++;assert.notEqual(f[0],f[1]);}else assert.ok(f.every(s=>s===f[0]));}assert.equal(n,20);assert.equal(m,10);assert.match(scene('dev-definitions','output',1),/Per person: 20,000/);assert.match(scene('dev-measures','inequality',1),/Mean: 20/);assert.match(scene('dev-causes','history',1),/not every country/);});

