test('genuine India1994/2024 pyramids convert source sex denominators and conserve total shares',()=>{const raw=JSON.parse(readFileSync(new URL('../dist/geography/data/india-population-wdi-response.json',import.meta.url),'utf8'));assert.equal(raw.response[0].lastupdated,'2026-10-08');assert.match(raw.sha256,/^[a-f0-9]{64}$/);assert.deepEqual(indiaChangeData.population.years.map(p=>p.year),[1994,2024]);for(const p of indiaChangeData.population.years){assert.equal(p.sexCounts.MA+p.sexCounts.FE,p.total);assert.equal(p.bins.length,17);let total=0;for(const [i,b]of p.bins.entries()){const age=i<16?String(i*5).padStart(2,'0')+String(i*5+4).padStart(2,'0'):'80UP';for(const sex of ['MA','FE']){const r=raw.response[1].find(x=>x.date===String(p.year)&&x.indicator.id===`SP.POP.${age}.${sex}.5Y`);assert.equal(b.sexPercent[sex],r.value);assert.equal(b.totalPercent[sex],sexToTotalPercent(r.value,p.sexCounts[sex],p.total));assert.ok(b.totalPercent[sex]>=0&&b.totalPercent[sex]<8);total+=b.totalPercent[sex];}}assert.ok(Math.abs(total-100)<1e-10);assert.ok(Math.abs(p.ageShares.reduce((s,x)=>s+x,0)-100)<1e-10);}const [a,b]=indiaChangeData.population.years;assert.equal(a.lifeExpectancy,60.237);assert.equal(b.lifeExpectancy,72.235);assert.ok(b.ageShares[0]<a.ageShares[0]);assert.ok(b.ageShares[2]>a.ageShares[2]);assert.match(indiaPyramid(1994),/total population as its denominator/);assert.match(indiaChangeEvidence('pyramids'),/80\+/);assert.doesNotMatch(indiaChangeEvidence('pyramids'),/broader youngest|smaller share in2024|correct answer/);});
