import {energy01Lessons,energyTopic} from '../dist/geography/content-energy01.js';
import {energy01Views,energy01Animated,energy01Evidence,energy01Data,energyUseBin,energyShare} from '../dist/geography/model-energy01.js';
test('Energy is scoped independently of landscapes and switching retains stable progress',()=>{assert.equal(energyTopic.id,'geography.a.energy');const shared=energy01Lessons[0],energy=energy01Lessons[1];for(const landscapes of [['coasts','rivers'],['coasts','glaciers'],['rivers','glaciers']])for(const resource of ['energy','water']){const p={landscapes,resource,physical:'coasts',human:'rural'};assert.ok(eligibleGeography(shared,p));assert.equal(eligibleGeography(energy,p),resource==='energy');const base={version:1,pathway:p,lessonId:shared.id,lessons:{[energy.id]:{seen:[0,1],observed:['finite'],practice:{[energy.practice[0].id]:{first:1,correct:false}}}}};assert.deepEqual(restore(JSON.stringify(base)).lessons,base.lessons);}assert.equal(eligibleGeography({...energy,option:'coasts'},{landscapes:['rivers','glaciers'],resource:'energy'}),false);assert.equal(eligibleGeography(undefined,null),false);assert.ok(eligibleGeography(energy,null));});
test('Energy pathways add four optional lessons without inflating Water progress',()=>{for(const[landscapes,water,energy]of [[['coasts','rivers'],117,131],[['coasts','glaciers'],120,134],[['rivers','glaciers'],121,135]])for(const[resource,n]of [['water',water],['energy',energy]])assert.equal(lessons.filter(l=>eligibleGeography(l,{landscapes,resource})).length,n);assert.deepEqual(energy01Lessons.map(l=>l.refs),[['6.2b'],['6.3a'],['6.3b'],['6.3c'],['6.4a']]);});
test('UK matched source cells retain denominator groups, quantities and neutral independent evidence',()=>{const d=JSON.parse(readFileSync(new URL('../dist/geography/data/energy01-uk-selected.json',import.meta.url),'utf8'));assert.deepEqual(d,energy01Data.uk);assert.match(d.xlsxSha256,/^[a-f0-9]{64}$/);assert.deepEqual(d.years,[1990,2025]);const a=d.rows.slice(0,5);for(const i of [1,2])assert.ok(Math.abs(a.reduce((s,r)=>s+r[i],0)-d.rows[5][i])<1e-10);assert.equal(Number((a[0][1]-a[0][2]).toFixed(2)),65.68);assert.equal(Number((a[1][2]+a[2][2]).toFixed(2)),120.75);assert.equal(energyShare(25,100),25);assert.equal(Number(energyShare(1.22+63.02+57.73,162.47).toFixed(1)),75.1);for(const s of ['mix','history']){const e=energy01Evidence(s);assert.match(e,/excludes non-energy use/);assert.match(e,/net imports/);assert.doesNotMatch(e,/120.75|65.68|correct answer|largest category/i);}});
test('consumption maps join actual dated values with explicit missing selection and unbiased stimulus',()=>{const raw=JSON.parse(readFileSync(new URL('../dist/geography/data/energy01-wdi-response.json',import.meta.url),'utf8'))[0];assert.equal(raw.response[0].lastupdated,'2026-10-08');for(const c of energy01Data.energy.countries)assert.equal(c.value,raw.response[1].find(x=>x.countryiso3code===c.code).value);assert.deepEqual([null,999,1000,1999,2000,3999,4000].map(energyUseBin),[-1,0,1,1,2,2,3]);assert.equal(energy01Data.water.rows.reduce((s,r)=>s+r[1],0),100);assert.match(energy01Evidence('energy'),/Grey countries are outside/);assert.doesNotMatch(energy01Evidence('energy'),/USA exceeds|UK is higher|correct answer/);assert.doesNotMatch(energy01Evidence('water'),/28%|correct answer/);});
test('twenty Energy views separate eight loops from twelve static charts or frameworks',()=>{let n=0,m=0;for(const l of energy01Lessons){assert.equal(l.tasks.length,4);for(const[v]of energy01Views[l.model]){n++;const f=[0,.5,1].map(t=>scene(l.model,v,t));assert.ok(f.every(s=>s.includes('role="img"')&&!/NaN|undefined|Infinity/.test(s)));assert.equal(isProcessView(l.model,v),energy01Animated(l.model,v));if(energy01Animated(l.model,v)){m++;assert.notEqual(f[0],f[1]);}else assert.ok(f.every(s=>s===f[0]));}}assert.equal(n,20);assert.equal(m,8);assert.match(scene('dev-energy-types','finite',1),/Stock: 80/);assert.match(scene('dev-energy-natural-gas','emissions',.5),/Different gases/);assert.match(scene('dev-energy-wind','low',.5),/not a calibrated/);});

import {energy02Lessons} from '../dist/geography/content-energy02.js';
import {energy02Data,energy02Views,energy02Animated,energy02Evidence,serviceDemand,indexedDemand} from '../dist/geography/model-energy02.js';
test('Energy02 covers five precise statements and keeps all lessons within the chosen resource route',()=>{assert.deepEqual(energy02Lessons.map(l=>l.refs),[['6.4b'],['6.5a'],['6.5b'],['6.5c'],['6.5d']]);for(const l of energy02Lessons){assert.equal(l.resourceOption,'energy');assert.equal(eligibleGeography(l,{landscapes:['coasts','rivers'],resource:'water'}),false);assert.equal(eligibleGeography(l,{landscapes:['coasts','rivers'],resource:'energy'}),true);}const l=energy02Lessons[2];assert.equal(l.tasks.length,5);assert.deepEqual(requirements[l.model],['coal','oil','gas','uranium','tradeoffs']);});
test('dated country profiles preserve primary consumption shares and explicitly avoid matched-year inference',()=>{const d=JSON.parse(readFileSync(new URL('../dist/geography/data/energy02-selected.json',import.meta.url),'utf8'));assert.deepEqual(d,energy02Data);assert.deepEqual(d.profiles.map(p=>p.year),[2023,2024]);for(const p of d.profiles)assert.equal(p.rows.reduce((s,r)=>s+r[1],0),100);assert.equal(d.profiles[0].rows.find(r=>r[0]==='Coal')[1],59);assert.equal(d.profiles[0].rows.find(r=>r[0]==='Hydro (rounded)')[1],0);for(const k of ['india','us']){const e=energy02Evidence(k);assert.match(e,/Different years/);assert.match(e,/rounded zero does not establish no use/);assert.doesNotMatch(e,/88%|largest reported|correct answer/);}assert.match(energy02Evidence('india'),/Hydro rounds to0%; it is not absent/);});
test('revised demand rates distinguish growth levels, rates and service intensity arithmetic',()=>{assert.deepEqual(energy02Data.growth.rates,[[2024,2],[2025,1.3]]);assert.equal(serviceDemand(20,2),40);assert.equal(serviceDemand(30,1.5),45);assert.ok(Math.abs(indexedDemand(100,1.3)-101.3)<1e-10);assert.ok(indexedDemand(100,1.3)>100);assert.equal(Number((2-1.3).toFixed(1)),.7);const e=energy02Evidence('growth');assert.doesNotMatch(e,/0.7 percentage|demand fell|correct answer/);assert.match(e,/not the level of energy consumption/);});
test('historical population and genuine future trajectory do not masquerade as measured energy series',()=>{assert.deepEqual(energy02Data.population.rows,[[1927,2],[1974,4],[2022,8]]);assert.match(scene('dev-energy2-demand-change','history'),/not.*annual measured global-energy series/);const e=energy02Evidence('projection');assert.match(e,/not an annual UNseries or an observed future/);assert.match(e,/conditional/);assert.doesNotMatch(e,/energy exhaustion|correct answer/);});
test('twenty-one views distinguish eleven process loops from ten static maps and evidence views',()=>{let n=0,m=0;for(const l of energy02Lessons)for(const[v]of energy02Views[l.model]){n++;const f=[0,.5,1].map(t=>scene(l.model,v,t));assert.ok(f.every(s=>s.includes('role="img"')&&!/NaN|undefined|Infinity/.test(s)));assert.equal(isProcessView(l.model,v),energy02Animated(l.model,v));if(energy02Animated(l.model,v)){m++;assert.notEqual(f[0],f[1]);}else assert.ok(f.every(s=>s===f[0]));}assert.equal(n,21);assert.equal(m,11);});
test('fracking, nuclear, HEP and PV models preserve key mechanism distinctions and limits',()=>{assert.match(scene('dev-energy2-fracking','fracture',.5),/proppant is not a new fuel/);assert.match(scene('dev-energy2-fracking','produce',.5),/does not create methane/);assert.match(scene('dev-energy2-fracking','risks'),/wastewater disposal injection/);assert.match(scene('dev-energy2-nonrenewable-development','uranium',.5),/Fission is not fossil combustion/);assert.match(scene('dev-energy2-renewable-development','hep',.5),/released rather than burned/);assert.match(scene('dev-energy2-renewable-development','solar',.5),/no turbine inside a cell/);});

import {energy03Lessons} from '../dist/geography/content-energy03.js';
import {energy03Data,energy03Maps,energy03Views,energy03Animated,energy03Evidence,stockEnd,percentSaving,capacityShare,regionXY} from '../dist/geography/model-energy03.js';

test('Energy03 builds the five stable planned IDs with option scope and two distinct country cases',()=>{assert.deepEqual(energy03Lessons.map(l=>l.id),['stakeholders','sustainable-use','management-views','developed-case','emerging-case'].map(s=>'geography.a.energy.'+s));assert.deepEqual(energy03Lessons.map(l=>l.refs),[['6.6a'],['6.7a'],['6.7b'],['6.7c'],['6.7c']]);assert.deepEqual(energy03Lessons.slice(3).map(l=>l.caseStudy),['germany','india']);for(const l of energy03Lessons){assert.equal(l.resourceOption,'energy');assert.ok(eligibleGeography(l,{landscapes:['rivers','glaciers'],resource:'energy'}));assert.equal(eligibleGeography(l,{landscapes:['rivers','glaciers'],resource:'water'}),false);assert.equal(l.tasks.length,4);}});
test('Energy03 selected source records retain hash-verifiable snapshots, dates and actual outcome boundaries',()=>{const raw=JSON.parse(readFileSync(new URL('../dist/geography/data/energy03-selected.json',import.meta.url),'utf8'));assert.deepEqual(raw,energy03Data);for(const s of raw.sources){const bytes=readFileSync(new URL(`../dist/geography/data/energy03-${s.id}-source.txt`,import.meta.url));assert.equal(createHash('sha256').update(bytes).digest('hex'),s.sha256);}assert.equal(raw.germany.updated,'19 October 2026');assert.equal(raw.india.date,'30 June 2025');assert.equal(raw.rooftop.date,'20 March 2026');assert.equal(raw.attitudes.published,'2 July 2026');assert.match(energy03Evidence('rooftop'),/projected jobs and avoided emissions are not treated as measured outcomes/);});
test('Germany indicators preserve their separate consumption denominators and do not leak calculated check answers',()=>{assert.deepEqual(energy03Data.germany.rows.map(r=>r[1]),[23.9,55.1,19.2,8]);assert.equal(Number((55.1-19.2).toFixed(1)),35.9);const e=energy03Evidence('germany');assert.match(e,/Each row has its own denominator/);assert.doesNotMatch(e,/35.9|102.2|correct answer/);assert.match(e,/19 October 2026/);assert.match(e,/RED/);});
test('India capacity distinguishes renewable and nonfossil subtotals, MW and GW, without double counting',()=>{const d=energy03Data.india;assert.equal(Number(d.rows.reduce((s,r)=>s+r[1],0).toFixed(2)),d.total);assert.equal(Number((d.rows[1][1]+d.rows[2][1]).toFixed(2)),d.nonFossil);assert.equal(Number(capacityShare(d.nonFossil,d.total).toFixed(2)),d.reportedNonFossilPercent);assert.equal(Number((d.nonFossil-234).toFixed(2)),8.78);assert.equal(Number((energy03Data.rooftop.addedMW/1000).toFixed(2)),9.57);assert.match(energy03Evidence('india'),/subtotal is not an extra category/);assert.doesNotMatch(energy03Evidence('rooftop'),/9.57|correct answer/);assert.equal(percentSaving(120,90),25);assert.equal(stockEnd(80,10,25),65);assert.equal(stockEnd(100,0,20),80);});
test('regional country maps retain actual geometry and reversible projection with explicit context limits',()=>{const g=JSON.parse(readFileSync(new URL('../dist/geography/data/world-natural-earth.geojson',import.meta.url),'utf8'));for(const[region,map]of Object.entries(energy03Maps))for(const p of map.paths){const f=g.features.find(x=>x.properties.ADM0_A3===p.code);assert.ok(f);const polys=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];const[x,y]=regionXY(region,...polys[0][0][0]);assert.ok(p.d.startsWith('M'+x.toFixed(2)+','+y.toFixed(2)));}for(const k of ['dev-energy3-developed-case','dev-energy3-emerging-case']){const e=scene(k,'map');assert.match(e,/clip-path/);assert.match(e,/not project footprints/);assert.match(e,/Natural Earth/);}});
test('twenty Energy03 views separate ten process loops from ten still maps, survey and source comparisons',()=>{let n=0,m=0;for(const l of energy03Lessons)for(const[v]of energy03Views[l.model]){n++;const f=[0,.5,1].map(t=>scene(l.model,v,t));assert.ok(f.every(s=>s.includes('role="img"')&&!/NaN|undefined|Infinity/.test(s)));assert.equal(isProcessView(l.model,v),energy03Animated(l.model,v));if(energy03Animated(l.model,v)){m++;assert.notEqual(f[0],f[1]);}else assert.ok(f.every(s=>s===f[0]));}assert.equal(n,20);assert.equal(m,10);assert.match(scene('dev-energy3-sustainable-use','finite',1),/End: 80 units/);assert.match(scene('dev-energy3-sustainable-use','renewal',1),/End: 65 units/);assert.match(energy03Evidence('attitudes'),/not complementary percentages/);assert.doesNotMatch(energy03Evidence('attitudes'),/actual bills will|correct answer/);});
